import pytest
from functools import wraps
from unittest.mock import MagicMock, patch

from django.utils.decorators import (
    classonlymethod,
    method_decorator,
    decorator_from_middleware,
    decorator_from_middleware_with_args,
    make_middleware_decorator,
    sync_and_async_middleware,
    sync_only_middleware,
    async_only_middleware,
    _multi_decorate,
)


# Helper decorators for testing
def simple_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.decorator_attr = 'test_attr'
    return wrapper


def another_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper


def add_prefix_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return 'prefix_' + result if isinstance(result, str) else result
    return wrapper


# ==================== Tests for classonlymethod ====================

class TestClassonlymethod:
    def test_accessible_on_class(self):
        class MyClass:
            @classonlymethod
            def my_method(cls):
                return 'class_method'

        result = MyClass.my_method()
        assert result == 'class_method'

    def test_not_accessible_on_instance(self):
        class MyClass:
            @classonlymethod
            def my_method(cls):
                return 'class_method'

        instance = MyClass()
        with pytest.raises(AttributeError) as exc_info:
            instance.my_method()
        assert "This method is available only on the class, not on instances." in str(exc_info.value)

    def test_classonlymethod_is_subclass_of_classmethod(self):
        assert issubclass(classonlymethod, classmethod)


# ==================== Tests for _multi_decorate ====================

class TestMultiDecorate:
    def test_single_decorator(self):
        def my_method(self):
            return 'result'

        wrapped = _multi_decorate(simple_decorator, my_method)

        class MyClass:
            pass

        instance = MyClass()
        result = wrapped(instance)
        assert result == 'result'

    def test_multiple_decorators_list(self):
        call_order = []

        def dec1(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append('dec1')
                return func(*args, **kwargs)
            return wrapper

        def dec2(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append('dec2')
                return func(*args, **kwargs)
            return wrapper

        def my_method(self):
            return 'result'

        wrapped = _multi_decorate([dec1, dec2], my_method)

        class MyClass:
            pass

        instance = MyClass()
        result = wrapped(instance)
        assert result == 'result'
        assert 'dec1' in call_order
        assert 'dec2' in call_order

    def test_preserves_method_name(self):
        def my_method(self):
            """My docstring"""
            return 'result'

        wrapped = _multi_decorate(simple_decorator, my_method)
        assert wrapped.__name__ == 'my_method'

    def test_copies_decorator_attributes(self):
        def my_method(self):
            return 'result'

        wrapped = _multi_decorate(simple_decorator, my_method)
        assert hasattr(wrapped, 'decorator_attr')
        assert wrapped.decorator_attr == 'test_attr'

    def test_with_args_and_kwargs(self):
        def my_method(self, x, y=10):
            return x + y

        wrapped = _multi_decorate(simple_decorator, my_method)

        class MyClass:
            pass

        instance = MyClass()
        result = wrapped(instance, 5, y=20)
        assert result == 25


# ==================== Tests for method_decorator ====================

class TestMethodDecorator:
    def test_decorate_function(self):
        @method_decorator(simple_decorator)
        def my_view(request):
            return 'view_result'

        result = my_view('request')
        assert result == 'view_result'

    def test_decorate_method_in_class(self):
        @method_decorator(simple_decorator, name='my_method')
        class MyClass:
            def my_method(self):
                return 'method_result'

        instance = MyClass()
        result = instance.my_method()
        assert result == 'method_result'

    def test_decorate_class_without_name_raises(self):
        with pytest.raises(ValueError) as exc_info:
            @method_decorator(simple_decorator)
            class MyClass:
                def my_method(self):
                    return 'result'
        assert "The keyword argument `name` must be the name of a method" in str(exc_info.value)

    def test_decorate_class_with_wrong_name_raises(self):
        with pytest.raises(ValueError) as exc_info:
            @method_decorator(simple_decorator, name='nonexistent_method')
            class MyClass:
                def my_method(self):
                    return 'result'
        assert "The keyword argument `name` must be the name of a method" in str(exc_info.value)

    def test_decorate_non_callable_attribute_raises(self):
        with pytest.raises(TypeError) as exc_info:
            @method_decorator(simple_decorator, name='my_attr')
            class MyClass:
                my_attr = 'not_callable'
        assert "Cannot decorate" in str(exc_info.value)

    def test_method_decorator_name(self):
        dec = method_decorator(simple_decorator)
        assert 'method_decorator' in dec.__name__

    def test_method_decorator_with_list_of_decorators(self):
        @method_decorator([simple_decorator, another_decorator], name='my_method')
        class MyClass:
            def my_method(self):
                return 'result'

        instance = MyClass()
        result = instance.my_method()
        assert result == 'result'

    def test_method_decorator_preserves_docstring(self):
        def my_method(self):
            """My docstring"""
            return 'result'

        decorated = method_decorator(simple_decorator)(my_method)
        assert decorated.__doc__ == 'My docstring'

    def test_method_decorator_with_class_without_name_empty_string(self):
        with pytest.raises(ValueError):
            @method_decorator(simple_decorator, name='')
            class MyClass:
                def my_method(self):
                    return 'result'

    def test_method_decorator_on_class_method(self):
        @method_decorator(simple_decorator, name='dispatch')
        class MyView:
            def dispatch(self, request):
                return 'dispatched'

        view = MyView()
        result = view.dispatch('request')
        assert result == 'dispatched'

    def test_method_decorator_with_decorator_without_name(self):
        # Test with a decorator that is a class instance (no __name__)
        class MyDecorator:
            def __call__(self, func):
                @wraps(func)
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)
                return wrapper

        dec_instance = MyDecorator()
        decorator = method_decorator(dec_instance)
        assert 'method_decorator' in decorator.__name__


