    def test_middleware_with_template_response(self):
        class TemplateMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_template_response(self, request, response):
                response.modified = True
                return response

            def process_response(self, request, response):
                response.response_processed = True
                return response

        decorator = make_middleware_decorator(TemplateMiddleware)()

        mock_response = MagicMock()
        mock_response.render = MagicMock()
        mock_response.render.return_value = mock_response

        @decorator
        def my_view(request):
            return mock_response

        result = my_view('request')
        assert result.modified is True
        # process_response is added as callback, not called directly
        mock_response.add_post_render_callback.assert_called_once()

