class TestIntegration:
    def test_method_decorator_on_class_based_view(self):
        call_log = []

        def logging_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_log.append('before')
                result = func(*args, **kwargs)
                call_log.append('after')
                return result
            return wrapper

        @method_decorator(logging_decorator, name='get')
        class MyView:
            def get(self, request):
                call_log.append('view')
                return 'response'

        view = MyView()
        result = view.get('request')
        assert result == 'response'
        assert call_log == ['before', 'view', 'after']

    def test_multiple_decorators_order(self):
        order = []

        def dec_a(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                order.append('a_before')
                result = func(*args, **kwargs)
                order.append('a_after')
                return result
            return wrapper

        def dec_b(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                order.append('b_before')
                result = func(*args, **kwargs)
                order.append('b_after')
                return result
            return wrapper

        @method_decorator([dec_a, dec_b], name='handle')
        class MyClass:
            def handle(self):
                order.append('handle')
                return 'done'

        instance = MyClass()
        instance.handle()
        # dec_a is outermost, dec_b is innermost
        assert order == ['a_before', 'b_before', 'handle', 'b_after', 'a_after']

    def test_middleware_full_pipeline(self):
        pipeline = []

        class FullMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_request(self, request):
                pipeline.append('process_request')
                return None

            def process_view(self, request, view_func, args, kwargs):
                pipeline.append('process_view')
                return None

            def process_response(self, request, response):
                pipeline.append('process_response')
                return response

        decorator = decorator_from_middleware(FullMiddleware)

        @decorator
        def my_view(request):
            pipeline.append('view')
            return 'response'

        result = my_view('request')
        assert result == 'response'
        assert pipeline == ['process_request', 'process_view', 'view', 'process_response']

    def test_method_decorator_applied_to_function_directly(self):
        results = []

        def tracking_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                results.append('decorated')
                return func(*args, **kwargs)
            return wrapper

        class MyView:
            @method_decorator(tracking_decorator)
            def my_method(self):
                results.append('method')
                return 'done'

        view = MyView()
        result = view.my_method()
        assert result == 'done'
        assert results == ['decorated', 'method']

    def test_renderable_response_callback_called(self):
        """Test that process_response is added as callback for renderable responses."""
        callbacks = []

        class ResponseMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_response(self, request, response):
                callbacks.append('process_response')
                return response

        decorator = decorator_from_middleware(ResponseMiddleware)

        mock_response = MagicMock()
        mock_response.render = MagicMock()

        @decorator
        def my_view(request):
            return mock_response

        result = my_view('request')
        # The callback should have been added
        mock_response.add_post_render_callback.assert_called_once()
        # Simulate calling the callback
        callback = mock_response.add_post_render_callback.call_args[0][0]
        callback(mock_response)
        assert 'process_response' in callbacks

"""
Unit tests for sphinx.environment.adapters.indexentries
"""

import pytest
from unittest.mock import MagicMock, patch
from sphinx.environment.adapters.indexentries import IndexEntries


def make_mock_builder():
    """Create a mock builder that returns predictable URIs."""
    builder = MagicMock()
    builder.get_relative_uri.return_value = 'genindex.html'
    return builder


def make_mock_env(entries=None):
    """Create a mock environment with given index entries."""
    env = MagicMock()
    domain = MagicMock()
    if entries is None:
        entries = {}
    domain.entries = entries
    env.get_domain.return_value = domain
    return env


def make_index_entries(entries_dict):
    """
    entries_dict: {filename: [(type, value, tid, main, index_key), ...]}
    """
    env = make_mock_env(entries_dict)
    return IndexEntries(env)


def test_create_index_empty():
    """Test with no index entries."""
    ie = make_index_entries({})
    builder = make_mock_builder()
    result = ie.create_index(builder)
    assert result == []


def test_create_index_single_simple():
    """Test single entry type with simple value."""
    entries = {
        'doc1': [('single', 'Python', 'id1', '', None)]
    }
    ie = make_index_entries(entries)
    builder = make_mock_builder()
    result = ie.create_index(builder)
    assert len(result) > 0
    # Find the 'P' group
    keys = [k for k, _ in result]
    assert 'P' in keys


def test_create_index_single_with_subentry():
    """Test single entry type with subentry."""
    entries = {
        'doc1': [('single', 'Python; language', 'id1', '', None)]
    }
    ie = make_index_entries(entries)
    builder = make_mock_builder()
    result = ie.create_index(builder)
    assert len(result) > 0
    # Check that Python entry exists with subentry
    for key, group in result:
        for entry_key, entry_val in group:
            if entry_key == 'Python':
                # entry_val[1] should have subitems
                assert len(entry_val[1]) > 0


def test_create_index_pair():
    """Test pair entry type."""
    entries = {
        'doc1': [('pair', 'Python; language', 'id1', '', None)]
    }
    ie = make_index_entries(entries)
    builder = make_mock_builder()
    result = ie.create_index(builder)
    # pair creates two entries: Python->language and language->Python
    all_keys = []
    for key, group in result:
        for entry_key, _ in group:
            all_keys.append(entry_key)
    assert 'Python' in all_keys
    assert 'language' in all_keys


